public static int nextPrime(int desiredCapacity) {
    int prime = desiredCapacity;
    while (true) {
        prime++;
        if (prime % 2 == 0 && prime >= 2) {
            continue;
        }
        int divisor = 3;
        while (divisor * divisor <= prime) {
