public static String unescapeId(String input) {
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            // handle escaped characters
            if (i + 1 < input.length()) {
                char nextChar = input.charAt(i + 1);
                switch (nextChar) {
                    case 'b':
                        output.append('\b');
                        i++;
                        break;
                    case 'f':
                        output.append('\f');
                        i++;
                        break;
                    case 'n':
                        output.append('\n');
                        i++;
                        break;
                    case 'r':
                        output.append('\r');
                        i++;
                        break;
                    case 't':
                        output.append('\t');
                        i++;
                        break;
                    case 'u':
                        try {
                            output.append((char) Integer.parseInt(input.substring(i + 2, i + 6), 16));
                            i += 5;
                        } catch (NumberFormatException e) {
                            // handle invalid unicode escape character
                        }
                        break;
                    default:
                        output.append(nextChar);
                        i++;
                }
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

