private List<Pair<List<Pair<Integer,Integer>>,E>> computeMinimalSeparators(E e) {
    // Initialize the list of minimal separators
    List<Pair<List<Pair<Integer,Integer>>,E>> minimalSeparators = new ArrayList<>();
    // Iterate over all vertices in the neighborhood of the current edge
    for (V v : graph.neighborhood(e)) {
        // Compute the list of minimal separators for the current vertex
        List<Pair<List<Pair<Integer,Integer>>,E>> vertexSeparators = computeMinimalSeparators(v);
        // Add the list of minimal separators for the current vertex to the global separator list
        minimalSeparators.addAll(vertexSeparators);
    }
    // Return the list of minimal separators for the current edge
    return minimalSeparators;
}

