public static void selectAndScroll(int row, JTable table, JScrollPane pane){

    table.setRowSelectionInterval(row, row);
    JViewport viewport = pane.getViewport();

    TableCellRenderer renderer = table.getCellRenderer(row, 0);
    Component comp = renderer.getTableCellRendererComponent(table, table.getValueAt(row, 0), true, true, row, 0);

    int width = viewport.getWidth();
    int height = comp.getPreferredSize().height;

    // Ensure that the cell is visible in the viewport
    Rectangle rect = table.getCellRect(row, 0, true);

    if(rect.y + height > viewport.getViewPosition().y + viewport.getHeight()){
        // Cell is not visible in the viewport; scroll upward
        int newY = rect.y - (height - (viewport.getViewPosition().y + viewport.getHeight() - rect.y));
        viewport.setViewPosition(new Point(viewport.getViewPosition().x, newY)); 
    }

    // Wait long enough for the table to repaint the selected row
    if(comp instanceof JComponent){
        try{
            Thread.sleep(20);
        }catch(InterruptedException ex){}
        // Force the table to repaint the newly selected row
        ((JComponent)comp).repaint();
    }
}

