public List<Integer> computeLowerBounds(List<K> keys) {
        Map<K, Integer> lowerBounds = new HashMap<>();

        for (int i = 0; i < keys.size() - 1; i++) {
            K key = keys.get(i);
            int lowerBound = i;
            for (int j = i + 1; j < keys.size(); j++) {
                K otherKey = keys.get(j);
                if (lessThan(otherKey, key)) {
                    lowerBound = j;
                    break;
                }
            }
            lowerBounds.put(key, lowerBound);
        }

        return new ArrayList<>(lowerBounds.values());
    }

private void pop(final String descriptor) {
    final int dimension = Type.getType(descriptor).getDimensions();
    for (int i = 0; i < dimension; i++) {
        final AbstractType value = this.outputFrame.pop();
        if (value == null) {
            throw new IllegalStateException("Not enough values on the stack");
        }
        if (!value.isReference()) {
            throw new IllegalStateException("Cannot pop value of type " + value.getClass().getSimpleName());
        }
        if (!value.getType().equals(Type.getType(descriptor))) {
            throw new IllegalStateException("Expected value of type " + Type.getType(descriptor) + " but got " + value.getType());
        }
    }
}

